#define main old_main
#include "scan.cpp"
#undef main
int main(int argc,char**argv){string root=argv[1];auto rr=fasta(root+"/target.fasta");ifstream in(root+"/independent_primers.tsv");ofstream out(root+"/nearest.tsv");out<<"name\taccession\tF\tR\tscore\tties\n";string l;while(getline(in,l)){istringstream ss(l);P p;if(!(ss>>p.name>>p.F>>p.R)||p.name.find("_original")==string::npos)continue;auto F=primer(p.F,0,0),R=primer(p.R,1,0);for(auto rec:rr){int best=99;set<pair<string,string>> tops;for(int ori=0;ori<2;ori++){auto s=rec.s;if(ori){reverse(s.begin(),s.end());for(auto &x:s)x=comp(x);}auto fs=scan(s,F,0,8),rs=scan(s,R,1,8);for(auto f:fs)for(auto r:rs){int total=r.pos+R.size()-f.pos;if(r.pos<f.pos+(int)F.size()||total<60||total>650||f.amb||r.amb)continue;int score=f.mm+r.mm;if(score>best)continue;string a,b;for(int j=0;j<(int)F.size();j++){int x=s[f.pos+j];a+=(x==1?'A':x==2?'C':x==4?'G':'T');}for(int j=R.size()-1;j>=0;j--){int x=comp(s[r.pos+j]);b+=(x==1?'A':x==2?'C':x==4?'G':'T');}if(score<best){best=score;tops.clear();}tops.insert({a,b});}}if(tops.size()==1)out<<p.name<<'\t'<<rec.id<<'\t'<<tops.begin()->first<<'\t'<<tops.begin()->second<<'\t'<<best<<'\t'<<tops.size()<<'\n';}}}
